* { box-sizing: border-box; }:root { --ink: #19345c; --page: #f6f9ff; --blue: #245edb; --blue-hover: #1948b1; --navy: #163b83; --soft-blue: #e8f0ff; --muted-blue: #506a8e; --border: #ccd9ee; --focus: #78a7ff; --on-accent: #fff; color: var(--ink); background: var(--page); font-synthesis: none; font-family: Manrope, ui-sans-serif, system-ui, sans-serif; }body { margin: 0px; }:root[data-store-theme="forest"] { --ink: #203e31; --page: #f5f9f5; --blue: #326750; --blue-hover: #24513d; --navy: #244b38; --soft-blue: #e4efe5; --muted-blue: #506d59; --border: #cbdccf; --focus: #70a887; }:root[data-store-theme="clay"] { --ink: #573427; --page: #fff8f4; --blue: #a54f35; --blue-hover: #863d27; --navy: #79412f; --soft-blue: #f7e7dc; --muted-blue: #825e4d; --border: #e7d1c3; --focus: #d68c67; }:root[data-store-theme="plum"] { --ink: #423050; --page: #faf7fd; --blue: #79529c; --blue-hover: #603d81; --navy: #523767; --soft-blue: #efe6f7; --muted-blue: #746080; --border: #ddcfe8; --focus: #b28ace; }:root[data-store-theme="graphite"] { --ink: #2e3742; --page: #f7f8fa; --blue: #4b5563; --blue-hover: #35404c; --navy: #303b48; --soft-blue: #e8ecf1; --muted-blue: #606c7c; --border: #d3dae3; --focus: #899bb2; }button, a { -webkit-tap-highlight-color: transparent; }button { color: inherit; cursor: pointer; font: inherit; }a { color: inherit; }button:focus-visible, input:focus-visible, a:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }.demo-banner { background: var(--navy); text-align: center; color: var(--on-accent); padding: 10px 15px; font-size: 12px; }header { border-bottom: 1px solid var(--border); justify-content: space-between; align-items: center; gap: 20px; margin: auto; padding: 24px 40px; display: flex; }.wordmark { letter-spacing: -0.07em; font-size: 27px; font-weight: 750; text-decoration: none; }.wordmark span { vertical-align: top; letter-spacing: 0px; margin-left: 4px; font-size: 10px; }.cart-button { background: 0px 0px; border: 0px; align-items: center; gap: 9px; font-size: 12px; display: flex; }.header-actions { align-items: center; gap: 20px; display: flex; }.demo-button { background: 0px 0px; border: 0px; align-items: center; gap: 7px; min-height: 44px; padding: 0px; font-size: 12px; display: inline-flex; }.current-theme { background: var(--blue); }.cart-count { background: var(--soft-blue); border-radius: 50%; place-items: center; width: 22px; height: 22px; font-size: 10px; display: inline-grid; }main { margin: auto; padding: 0px 40px; }.hero { padding: 32px 0px 26px; }h1 { letter-spacing: -0.03em; margin: 0px; font-size: clamp(26px, 3vw, 36px); font-weight: 500; line-height: 1.2; }.shop-search { margin-top: 24px; }.collection-options, .theme-options { flex-wrap: wrap; gap: 8px; display: flex; }.collection-options { flex-wrap: nowrap; margin-top: 20px; padding-bottom: 4px; overflow-x: auto; }.collection-options button, .theme-options button { border: 1px solid var(--border); background: 0px 0px; border-radius: 5px; flex: 1 0 auto; justify-content: center; align-items: center; gap: 7px; min-height: 44px; padding: 9px 12px; font-size: 12px; display: inline-flex; }.theme-options button:hover { background: var(--soft-blue); }.collection-options button { color: var(--muted-blue); border-width: 0px 0px 2px; border-style: none none solid; border-color: currentcolor currentcolor rgba(0, 0, 0, 0); border-image: none; border-radius: 0px; padding: 12px 14px; }.collection-options button:hover { color: var(--ink); border-bottom-color: var(--border); }.collection-options button[aria-pressed="true"] { border-bottom-color: var(--ink); color: var(--ink); }.theme-options button[aria-pressed="true"] { background: var(--soft-blue); border-color: var(--blue); }.demo-popover { width: 280px; max-width: calc(-40px + 100vw); max-height: calc(-130px + 100vh); color: var(--ink); background: var(--page); border: 1px solid var(--border); border-radius: 8px; margin: 0px; padding: 18px; position: fixed; inset: 104px 40px auto auto; overflow-y: auto; box-shadow: rgba(25, 52, 92, 0.094) 0px 8px 24px; }.demo-title { margin-bottom: 14px; font-size: 13px; font-weight: 700; display: block; }.demo-section + .demo-section, .demo-section + .demo-reset { margin-top: 16px; }.demo-headline { gap: 8px; display: flex; }.demo-headline input { border: 1px solid var(--border); min-width: 0px; color: var(--ink); font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; background: 0px 0px; border-radius: 5px; flex: 1 1 0%; padding: 10px; font-size: 12px; }.demo-headline button { background: var(--blue); color: var(--on-accent); border: 0px; border-radius: 5px; padding: 0px 14px; font-size: 12px; }.demo-headline button:hover { background: var(--blue-hover); }.demo-reset { border-right: 0px; border-bottom: 0px; border-left: 0px; border-image: none; border-top: 1px solid var(--border); width: 100%; color: var(--muted-blue); text-align: left; background: 0px 0px; margin-top: 16px; padding: 14px 0px 0px; font-size: 12px; text-decoration: underline; display: block; }.theme-label { margin-bottom: 10px; font-size: 12px; display: block; }.theme-swatch { border-radius: 50%; width: 14px; height: 14px; }.shop-search label { margin-bottom: 10px; font-size: 13px; display: block; }.search-field { border: 1px solid var(--border); border-radius: 5px; align-items: center; gap: 10px; padding: 8px 8px 8px 14px; display: flex; }.search-field > svg { flex-shrink: 0; }.search-field input { width: 100%; min-width: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; color: var(--muted-blue); background: 0px 0px; border: 0px; padding: 8px 0px; font-size: 14px; }.search-field input::placeholder { color: var(--muted-blue); opacity: 0.8; }.search-field button { background: var(--blue); color: var(--on-accent); border: 0px; border-radius: 3px; padding: 12px 16px; font-size: 13px; }.search-status { overflow-wrap: anywhere; margin: 8px 0px 0px; font-size: 12px; }.search-status:empty { display: none; }.example-searches { flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 14px; display: flex; }.example-label { color: var(--muted-blue); font-size: 12px; }.example-searches button { border: 1px solid var(--border); min-height: 36px; color: var(--muted-blue); background: 0px 0px; border-radius: 999px; padding: 8px 14px; font-size: 12px; }.example-searches button:hover { background: var(--soft-blue); color: var(--ink); }.clear-search { color: inherit; white-space: nowrap; background: 0px 0px; border: 0px; padding: 10px 0px; font-size: 12px; text-decoration: underline; }.shipping-info { background: var(--soft-blue); border-radius: 5px; width: fit-content; margin-top: 20px; padding: 11px 14px; font-size: 12px; }.collection { padding-bottom: 60px; }.section-heading { border-top: 1px solid var(--border); justify-content: space-between; align-items: center; gap: 15px; padding: 25px 0px; display: flex; }h2 { margin: 0px; font-size: 15px; font-weight: 600; }.products { grid-template-columns: repeat(3, minmax(0px, 1fr)); gap: 52px 28px; display: grid; }.product { flex-direction: column; min-width: 0px; display: flex; }.product-gallery { grid-template-rows: auto 66px; min-width: 0px; display: grid; }.product-art { aspect-ratio: 1 / 1; border-radius: 3px; justify-content: center; align-items: center; display: flex; position: relative; overflow: hidden; }.sage { background: var(--soft-blue); }.sand { background: rgb(237, 242, 250); }.clay { background: rgb(230, 237, 249); }.product-art img { object-fit: cover; width: 100%; height: 100%; display: block; }.product-photo { width: 100%; height: 100%; display: block; position: relative; overflow: hidden; }.product-thumbnails { gap: 8px; min-width: 0px; margin-top: 10px; padding-bottom: 4px; display: flex; overflow-x: auto; }.product-thumbnails button { background: 0px 0px; border: 1px solid rgba(0, 0, 0, 0); border-radius: 3px; flex-shrink: 0; width: 56px; height: 56px; padding: 2px; }.product-thumbnails button[aria-pressed="true"] { border-color: var(--blue); }.product-thumbnails button:hover { border-color: var(--focus); }.product-thumbnails img { object-fit: cover; border-radius: 2px; width: 100%; height: 100%; display: block; }.product-heading { justify-content: space-between; align-items: start; gap: 10px; min-height: 22px; margin-top: 12px; display: flex; }h3 { margin: 0px; font-size: 14px; font-weight: 600; }.product-heading span { white-space: nowrap; font-size: 12px; }.add-button { color: var(--ink); border: 1px solid var(--border); background: 0px 0px; border-radius: 3px; justify-content: center; align-items: center; gap: 8px; width: 100%; margin-top: auto; padding: 12px; font-size: 12px; display: flex; }.add-button:hover { background: var(--blue); border-color: var(--blue); color: var(--on-accent); }.product-colors { flex-wrap: wrap; align-items: center; gap: 0px; margin: 6px 0px 12px; display: flex; }.product-colors button { background: 0px 0px; border: 0px; border-radius: 50%; place-items: center; width: 40px; min-height: 44px; padding: 0px; display: inline-grid; }.product-colors button:hover .color-swatch { box-shadow: 0 0 0 3px var(--page), 0 0 0 4px var(--border); }.product-colors button[aria-pressed="true"] .color-swatch { box-shadow: 0 0 0 3px var(--page), 0 0 0 4px var(--muted-blue); }.color-swatch { border: 1px solid rgba(0, 0, 0, 0.133); border-radius: 50%; flex-shrink: 0; width: 22px; height: 22px; }.selected-color { color: var(--muted-blue); margin-left: 10px; font-size: 12px; }.added-message { height: 16px; font-size: 12px; }footer { border-top: 1px solid var(--border); justify-content: space-between; align-items: center; gap: 25px; margin: auto; padding: 30px 40px; display: flex; }footer .wordmark { font-size: 20px; }.cart-page, .confirmation { max-width: 640px; min-height: 68vh; margin: auto; padding: 80px 0px 100px; }.cart-page h1, .confirmation h1 { font-size: 32px; }.cart-page > p, .confirmation > p { color: var(--muted-blue); font-size: 14px; line-height: 1.7; }.cart-items { border-top: 1px solid var(--border); margin: 35px 0px 20px; }.cart-items > div { border-bottom: 1px solid var(--border); justify-content: space-between; padding: 20px 0px; font-size: 14px; display: flex; }.cart-items small { color: var(--muted-blue); margin-left: 10px; }.cart-summary { margin: 26px 0px; font-size: 14px; }.cart-summary > div { justify-content: space-between; padding: 6px 0px; display: flex; }.cart-summary .cart-grand-total { border-top: 1px solid var(--border); margin-top: 8px; padding-top: 14px; }.demo-note { background: var(--soft-blue); border-radius: 4px; padding: 16px; font-size: 12px !important; }.primary-button { background: var(--blue); color: var(--on-accent); border: 0px; border-radius: 3px; margin-top: 10px; padding: 14px 25px; font-size: 13px; }.search-field button:hover, .primary-button:hover { background: var(--blue-hover); }.text-button { color: var(--muted-blue); background: 0px 0px; border: 0px; margin-top: 12px; padding: 12px; font-size: 12px; display: block; }.confirmation { text-align: center; }.checkmark { background: var(--soft-blue); border-radius: 50%; place-items: center; width: 60px; height: 60px; margin-bottom: 15px; font-size: 30px; display: inline-grid; }.receipt { border: 1px solid var(--border); margin: 30px 0px 20px; padding: 20px; font-size: 13px; }@media (width <= 1099px) {
  .products { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
}@media (width <= 700px) {
  .header-actions { gap: 12px; }
  .demo-popover { right: 20px; }
  header { padding: 20px; }
  main { padding: 0px 20px; }
  .search-field input { font-size: 16px; }
  .hero { padding: 28px 0px 22px; }
  .products { grid-template-columns: 1fr; gap: 44px; }
  .section-heading { flex-direction: column; align-items: start; }
  footer { flex-wrap: wrap; gap: 15px; padding: 25px 20px; }
  .cart-page, .confirmation { padding-top: 50px; }
}@media (width <= 560px) {
  .cart-button-label { display: none; }
}
